userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:bold">Guided demo</span>
<label>Focus representation <select id="representationFocusInput" onchange="update_representationFocus(this.value)"><option>Graph</option><option>Adjacency list</option><option>Adjacency matrix</option></select></label>
<button id="modifyEdgeInput" onclick="trigger_modifyEdge()">Add/remove selected edge</button>
<span id="editStatus" style="font-size:11px;color:#444">Click an edge, matrix 1, list record, or vertex.</span>
<span id="demoNarration" style="display:block;margin:0;font-size:10px;max-width:240px"></span>
<span><button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 1800, 460);

var g = draw.group();
var edgeLayer = g.group();
var nodeLayer = g.group();
var listLayer = g.group();
var matrixLayer = g.group();
var labelLayer = g.group();

var baseEdges = [[1,2],[1,5],[2,5],[2,3],[2,4],[3,4],[4,5]];
var edgeSet = {};
baseEdges.forEach(function(e){ edgeSet[key(e[0], e[1])] = true; });

var graphPos = {
  1:{x:50,y:145}, 2:{x:230,y:145}, 3:{x:350,y:235}, 4:{x:230,y:325}, 5:{x:50,y:325}
};
var selectedEdge = null;
var selectedVertex = null;
var selectedPair = [];
var focusRep = 'Graph';
var editMode = 'idle';
var currentStep = 0;

var colors = {
  gray:'#d9d9d9',
  line:'#000000',
  blue:'#6db7ff',
  orange:'#f28c28',
  orangeLight:'#ffe0bd',
  yellow:'#fff28a',
  yellow2:'#fff7b5',
  dim:'#b7b7b7',
  panel:'#3b82f6'
};

var arrowMarker = draw.marker(13, 9, function(add) {
  add.path('M0,0 L13,4.5 L0,9 Z').fill('#000');
});
arrowMarker.ref(13, 4.5).orient('auto');

function key(a,b){ return Math.min(a,b) + '-' + Math.max(a,b); }
function hasEdge(a,b){ return !!edgeSet[key(a,b)]; }
function setEdge(a,b,on){
  if (a === b) return;
  if (on) edgeSet[key(a,b)] = true;
  else delete edgeSet[key(a,b)];
}
function parseKey(k){ return k.split('-').map(function(x){return +x;}); }

function textCenter(parent, x, y, s, size) {
  return parent.text(String(s)).font({ family:'Times New Roman, serif', size:size || 34 })
    .attr({'text-anchor':'middle','dominant-baseline':'middle'}).center(x, y);
}
function haloText(parent, x, y, s, size) {
  return textCenter(parent, x, y, s, size).attr({
    'paint-order':'stroke', stroke:'#fff', 'stroke-width':4, 'stroke-linejoin':'round'
  });
}
function hArrow(parent, x1, y, x2, color, width) {
  return parent.line(x1, y, x2, y).stroke({color:color || '#000', width:width || 2})
    .marker('end', arrowMarker);
}

function adjList() {
  var adj = {1:[],2:[],3:[],4:[],5:[]};
  Object.keys(edgeSet).forEach(function(k) {
    var p = parseKey(k);
    adj[p[0]].push(p[1]);
    adj[p[1]].push(p[0]);
  });
  var original = {
    1:[2,5,3,4],
    2:[1,5,3,4],
    3:[2,4,1,5],
    4:[2,5,3,1],
    5:[4,1,2,3]
  };
  for (var v=1; v<=5; v++) {
    adj[v].sort(function(a,b) {
      return original[v].indexOf(a) - original[v].indexOf(b);
    });
  }
  return adj;
}

function selectEdge(a,b, fromClick) {
  selectedEdge = [Math.min(a,b), Math.max(a,b)];
  selectedVertex = null;
  selectedPair = [a,b];
  editMode = 'idle';
  renderAll();
  if (fromClick) showPopup(
    'One undirected edge, two stored entries',
    'Edge {' + selectedEdge[0] + ',' + selectedEdge[1] + '} is one line in the graph. It is stored twice in the adjacency lists and twice as symmetric matrix entries.'
  );
}

function selectVertex(v, fromClick) {
  if (editMode === 'selectingVertices') {
    if (selectedPair.indexOf(v) < 0) {
      if (selectedPair.length >= 2) selectedPair = [];
      selectedPair.push(v);
    }
    selectedVertex = v;
    selectedEdge = selectedPair.length === 2 ? [Math.min(selectedPair[0], selectedPair[1]), Math.max(selectedPair[0], selectedPair[1])] : null;
    renderAll();
    return;
  }
  selectedVertex = v;
  selectedEdge = null;
  selectedPair = [v];
  renderAll();
  if (fromClick) showPopup(
    'Vertex neighborhood',
    'Vertex ' + v + ' has the same neighbors in all three views: incident graph edges, records in row ' + v + ' of the list, and 1s in row/column ' + v + ' of the matrix.'
  );
}

function drawGraph() {
  edgeLayer.clear(); nodeLayer.clear();
  Object.keys(edgeSet).forEach(function(k) {
    var p = parseKey(k), a = p[0], b = p[1];
    var pa = graphPos[a], pb = graphPos[b];
    var selected = selectedEdge && key(a,b) === key(selectedEdge[0], selectedEdge[1]);
    var incident = selectedVertex && (a === selectedVertex || b === selectedVertex);
    var line = edgeLayer.line(pa.x, pa.y, pb.x, pb.y).stroke({
      color: selected ? colors.orange : (incident ? '#3b82f6' : colors.line),
      width: selected ? 6 : (incident ? 4 : 2)
    });
    line.css('cursor','pointer')
      .on('mousemove', function(e){ showTooltip('Graph edge {' + a + ',' + b + '}', e); })
      .on('mouseleave', function(){ hideTooltip(); })
      .on('click', function(){ selectEdge(a,b,true); });
  });
  if (selectedEdge && !hasEdge(selectedEdge[0], selectedEdge[1])) {
    var p1 = graphPos[selectedEdge[0]], p2 = graphPos[selectedEdge[1]];
    edgeLayer.line(p1.x, p1.y, p2.x, p2.y).stroke({color:colors.orange, width:4, dasharray:'8 7'});
  }
  for (var v=1; v<=5; v++) {
    var p = graphPos[v];
    var chosen = selectedVertex === v || selectedPair.indexOf(v) >= 0;
    var c = nodeLayer.circle(60).center(p.x, p.y).fill(chosen ? colors.blue : colors.gray)
      .stroke({color:'#000', width:2});
    c.css('cursor','pointer')
      .on('mousemove', (function(vv){ return function(e){ showTooltip('Vertex ' + vv, e); }; })(v))
      .on('mouseleave', function(){ hideTooltip(); })
      .on('click', (function(vv){ return function(){ selectVertex(vv,true); }; })(v));
    textCenter(nodeLayer, p.x, p.y, v, 38);
  }
  haloText(nodeLayer, 200, 415, '(a)', 38);
}

function isSelectedListRecord(row, neighbor) {
  if (selectedEdge && hasEdge(selectedEdge[0], selectedEdge[1])) {
    return (row === selectedEdge[0] && neighbor === selectedEdge[1]) ||
           (row === selectedEdge[1] && neighbor === selectedEdge[0]);
  }
  return false;
}

function drawRecord(parent, x, y, row, val, isLast) {
  var w = 120, h = 52, half = 60;
  var recSelected = isSelectedListRecord(row, val);
  var rowFocus = selectedVertex === row;
  parent.rect(w,h).move(x,y).fill(recSelected ? colors.yellow : (rowFocus ? colors.yellow2 : colors.gray))
    .stroke({color:'#000', width:2});
  parent.line(x+half,y,x+half,y+h).stroke({color:'#000', width:2});
  textCenter(parent, x+half/2, y+h/2, val, 34);
  if (isLast) {
    parent.line(x+half+18, y+h-10, x+w-16, y+10).stroke({color:'#000', width:3});
  } else {
    textCenter(parent, x+half+half/2, y+h/2-2, '—', 30);
  }
  var hit = parent.rect(w,h).move(x,y).fill({color:'#fff', opacity:0});
  hit.css('cursor','pointer')
    .on('mousemove', function(e){ showTooltip('List entry: vertex ' + row + ' stores neighbor ' + val, e); })
    .on('mouseleave', function(){ hideTooltip(); })
    .on('click', function(){ selectEdge(row, val, true); });
}

function drawList() {
  listLayer.clear();
  var adj = adjList();
  var arrayX = 580, rowY0 = 55, rowGap = 60, cellW = 60, cellH = 60;
  var recX0 = 670, recGap = 150, recH = 52;
  for (var r=1; r<=5; r++) {
    var y = rowY0 + (r-1)*rowGap;
    haloText(listLayer, 550, y+cellH/2, r, 36);
    listLayer.rect(cellW,cellH).move(arrayX,y).fill(selectedVertex === r ? colors.yellow2 : colors.gray)
      .stroke({color:'#000', width:2});
    textCenter(listLayer, arrayX+cellW/2, y+cellH/2-2, '—', 30);
    var arrHit = listLayer.rect(cellW,cellH).move(arrayX,y).fill({color:'#fff', opacity:0});
    arrHit.css('cursor','pointer')
      .on('mousemove', (function(rr){ return function(e){ showTooltip('Header for adjacency list of vertex ' + rr, e); }; })(r))
      .on('mouseleave', function(){ hideTooltip(); })
      .on('click', (function(rr){ return function(){ selectVertex(rr,true); }; })(r));
    var vals = adj[r];
    if (vals.length) hArrow(listLayer, arrayX+cellW, y+cellH/2, recX0-8, '#000', 2);
    for (var i=0; i<vals.length; i++) {
      var x = recX0 + i*recGap;
      drawRecord(listLayer, x, y+4, r, vals[i], i === vals.length-1);
      if (i < vals.length-1) hArrow(listLayer, x+120, y+cellH/2, x+recGap-8, '#000', 2);
    }
  }
  haloText(listLayer, 880, 415, '(b)', 38);
}

function matrixValue(i,j){ return i === j ? 0 : (hasEdge(i,j) ? 1 : 0); }

function isSelectedMatrixCell(i,j) {
  if (i === j) return false;
  if (selectedEdge) return (i === selectedEdge[0] && j === selectedEdge[1]) || (i === selectedEdge[1] && j === selectedEdge[0]);
  return false;
}

function drawMatrix() {
  matrixLayer.clear();
  var x0 = 1478, y0 = 55, cell = 60;
  matrixLayer.rect(cell*5, cell*5).move(x0,y0).fill('#fff').stroke({color:'#000', width:2});
  for (var c=1; c<=5; c++) haloText(matrixLayer, x0+(c-0.5)*cell, 25, c, 36);
  for (var r=1; r<=5; r++) haloText(matrixLayer, x0-30, y0+(r-0.5)*cell, r, 36);
  for (var i=1; i<=5; i++) {
    for (var j=1; j<=5; j++) {
      var cx = x0+(j-0.5)*cell, cy = y0+(i-0.5)*cell;
      var sel = isSelectedMatrixCell(i,j);
      var rowCol = selectedVertex && (i === selectedVertex || j === selectedVertex) && matrixValue(i,j) === 1;
      if (sel || rowCol) {
        matrixLayer.rect(cell-8, cell-8).center(cx,cy).fill(sel ? colors.orangeLight : colors.yellow2)
          .stroke({color: sel ? colors.orange : '#3b82f6', width: sel ? 3 : 2});
      }
      textCenter(matrixLayer, cx, cy, matrixValue(i,j), 36);
      var hit = matrixLayer.rect(cell,cell).move(x0+(j-1)*cell, y0+(i-1)*cell).fill({color:'#fff', opacity:0});
      hit.css('cursor','pointer')
        .on('mousemove', (function(ii,jj){ return function(e){ showTooltip('Matrix cell (' + ii + ',' + jj + ') = ' + matrixValue(ii,jj), e); }; })(i,j))
        .on('mouseleave', function(){ hideTooltip(); })
        .on('click', (function(ii,jj){
          return function(){
            if (ii === jj) return;
            if (matrixValue(ii,jj) === 1) selectEdge(ii,jj,true);
            else {
              selectedEdge = [Math.min(ii,jj), Math.max(ii,jj)];
              selectedPair = [ii,jj];
              selectedVertex = null;
              renderAll();
            }
          };
        })(i,j));
    }
  }
  haloText(matrixLayer, 1628, 415, '(c)', 38);
}

function updateStatus() {
  var s = document.getElementById('editStatus');
  if (!s) return;
  if (editMode === 'selectingVertices') {
    s.textContent = selectedPair.length < 2
      ? 'Edit mode: click two vertices.'
      : 'Selected {' + selectedPair[0] + ',' + selectedPair[1] + '}; press the button to toggle it.';
  } else if (selectedEdge) {
    s.textContent = 'Selected edge {' + selectedEdge[0] + ',' + selectedEdge[1] + '} shows paired storage entries.';
  } else if (selectedVertex) {
    s.textContent = 'Selected vertex ' + selectedVertex + ': compare its neighbors in all views.';
  } else {
    s.textContent = 'Click an edge, matrix 1, list record, or vertex.';
  }
}

function renderAll() {
  drawGraph();
  drawList();
  drawMatrix();
  updateStatus();
}

function update_representationFocus(v) {
  focusRep = v;
  if (v === 'Graph' && !selectedVertex && !selectedEdge) selectedVertex = null;
  if ((v === 'Adjacency list' || v === 'Adjacency matrix') && !selectedVertex && !selectedEdge) selectedVertex = 2;
  renderAll();
}

function toggle_representationFocus(on) {
  update_representationFocus(on ? 'Adjacency list' : 'Graph');
}

function trigger_modifyEdge() {
  if (editMode !== 'selectingVertices' && (!selectedPair || selectedPair.length < 2)) {
    editMode = 'selectingVertices';
    selectedPair = [];
    selectedEdge = null;
    selectedVertex = null;
    renderAll();
    return;
  }
  if (!selectedPair || selectedPair.length < 2) {
    editMode = 'selectingVertices';
    renderAll();
    return;
  }
  var a = selectedPair[0], b = selectedPair[1];
  var existed = hasEdge(a,b);
  setEdge(a,b,!existed);
  selectedEdge = [Math.min(a,b), Math.max(a,b)];
  editMode = 'idle';
  renderAll();
  showPopup(
    existed ? 'Edge removed' : 'Edge added',
    'Toggling {' + a + ',' + b + '} changes one graph line, the entry ' + b + ' in list ' + a + ', the entry ' + a + ' in list ' + b + ', and matrix cells (' + a + ',' + b + ') and (' + b + ',' + a + ').'
  );
}

var demoSteps = [
  {
    title:'Same graph, three encodings',
    narration:"The left panel is the graph itself, the middle panel stores each vertex's neighbors in a linked list, and the right panel stores the same information as a 5-by-5 matrix. Focus on any representation to see that the neighbor relationships match across all three.",
    state:{representationFocus:'Graph', modifyEdge:'idle'}
  },
  {
    title:'Trace one edge',
    narration:'Click an edge such as 2-4 in the graph, or click either of its matrix 1s. The demo highlights edge 2-4, the list record 4 in vertex 2’s list, the list record 2 in vertex 4’s list, and the symmetric matrix cells (2,4) and (4,2).',
    state:{representationFocus:'Adjacency matrix', modifyEdge:'idle'}
  },
  {
    title:"Focus on one vertex's neighborhood",
    narration:'Switch focus to the adjacency list and select vertex 2. Its neighbors 1, 3, 4, and 5 appear as list records, as graph edges incident on vertex 2, and as 1s across row and column 2 of the matrix.',
    state:{representationFocus:'Adjacency list', modifyEdge:'idle'}
  },
  {
    title:'Edit an undirected edge',
    narration:'Select two vertices and press add/remove. The graph line appears or disappears, and the storage updates in pairs: one record in each affected adjacency list and two symmetric matrix entries.',
    state:{representationFocus:'Graph', modifyEdge:'selectingVertices'}
  }
];

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length-1, i));
  var st = demoSteps[currentStep].state;
  focusRep = st.representationFocus || 'Graph';
  editMode = st.modifyEdge || 'idle';
  var sel = document.getElementById('representationFocusInput');
  if (sel) sel.value = focusRep;
  if (currentStep === 0) {
    selectedEdge = null; selectedVertex = null; selectedPair = [];
  } else if (currentStep === 1) {
    selectedEdge = [2,4]; selectedVertex = null; selectedPair = [2,4];
  } else if (currentStep === 2) {
    selectedEdge = null; selectedVertex = 2; selectedPair = [2];
  } else if (currentStep === 3) {
    selectedEdge = [1,3]; selectedVertex = null; selectedPair = [1,3];
  }
  document.getElementById('demoNarration').textContent = demoSteps[currentStep].narration;
  document.getElementById('stepLabel').textContent = (currentStep+1) + ' / ' + demoSteps.length + ' — ' + demoSteps[currentStep].title;
  renderAll();
}

function nextStep(){ applyStep(currentStep + 1); }
function prevStep(){ applyStep(currentStep - 1); }

renderAll();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

