function key(a,b){ return Math.min(a,b) + '-' + Math.max(a,b); }
function hasEdge(a,b){ return !!edgeSet[key(a,b)]; }
function setEdge(a,b,on){
  if (a === b) return;
  if (on) edgeSet[key(a,b)] = true;
  else delete edgeSet[key(a,b)];
}
function parseKey(k){ return k.split('-').map(function(x){return +x;}); }

function textCenter(parent, x, y, s, size) {
  return parent.text(String(s)).font({ family:'Times New Roman, serif', size:size || 34 })
    .attr({'text-anchor':'middle','dominant-baseline':'middle'}).center(x, y);
}
function haloText(parent, x, y, s, size) {
  return textCenter(parent, x, y, s, size).attr({
    'paint-order':'stroke', stroke:'#fff', 'stroke-width':4, 'stroke-linejoin':'round'
  });
}
function hArrow(parent, x1, y, x2, color, width) {
