function adjList() {
  var adj = {1:[],2:[],3:[],4:[],5:[]};
  Object.keys(edgeSet).forEach(function(k) {
    var p = parseKey(k);
    adj[p[0]].push(p[1]);
    adj[p[1]].push(p[0]);
  });
  var original = {
    1:[2,5,3,4],
    2:[1,5,3,4],
    3:[2,4,1,5],
    4:[2,5,3,1],
    5:[4,1,2,3]
  };
  for (var v=1; v<=5; v++) {
    adj[v].sort(function(a,b) {
      return original[v].indexOf(a) - original[v].indexOf(b);
