  1:{x:42,y:145}, 2:{x:190,y:145}, 3:{x:292,y:236}, 4:{x:190,y:326}, 5:{x:42,y:326}
};

var rowOrder = {
  1:[2,5,3,4],
  2:[1,5,3,4],
  3:[2,4,1,5],
  4:[2,5,3,1],
  5:[4,1,2,3]
};

function resetEdgesOnly() {
  edgeSet = {};
  for (var i=0; i<baseEdges.length; i++) edgeSet[key(baseEdges[i][0], baseEdges[i][1])] = true;
}

resetEdgesOnly();

var arrowMarker = draw.marker(12, 8, function(add) {
  add.path('M0,0 L12,4 L0,8 Z').fill('#000');
});
arrowMarker.ref(12, 4).orient('auto');

function key(a,b){ return Math.min(a,b) + '-' + Math.max(a,b); }
function parseKey(k){ var p = k.split('-'); return [+p[0], +p[1]]; }
function hasEdge(a,b){ return !!edgeSet[key(a,b)]; }
function setEdge(a,b,on){
  if (a === b) return;
  if (on) edgeSet[key(a,b)] = true;
  else delete edgeSet[key(a,b)];
}

function textCenter(parent, x, y, s, size) {
  return parent.text(String(s)).font({ family:'Times New Roman, serif', size:size || 34 })
    .attr({'text-anchor':'middle','dominant-baseline':'middle'}).center(x, y);
}

function haloText(parent, x, y, s, size) {
  return textCenter(parent, x, y, s, size).attr({
    'paint-order':'stroke',
    stroke:'#fff',
    'stroke-width':5,
    'stroke-linejoin':'round'
  });
}

function hArrow(parent, x1, y, x2, color, width) {
  return parent.line(x1, y, x2, y).stroke({color:color || '#000', width:width || 2.2})
    .marker('end', arrowMarker);
}

function panelFrame(x,y,w,h,name) {
  var on = focusRep === name;
  var r = frameLayer.rect(w,h).move(x,y).rx(8).ry(8)
    .fill(on ? {color:colors.focusFill, opacity:0.7} : {color:'#fff', opacity:0})
    .stroke(on ? {color:colors.focusBlue, width:4, opacity:0.95} : {color:'#fff', width:0, opacity:0});
  if (on) {
    r.css('cursor','pointer')
      .on('mousemove', function(e){ showTooltip('Focused view: ' + name, e); })
      .on('mouseleave', function(){ hideTooltip(); })
      .on('click', function(){ showPopup('Focused representation', 'This blue outline marks the representation currently selected in the controls. The same selected edge or vertex is still shown in the other two representations.'); });
  }
}

function adjList() {
  var adj = {1:[],2:[],3:[],4:[],5:[]};
  var ks = Object.keys(edgeSet);
  for (var i=0; i<ks.length; i++) {
    var p = parseKey(ks[i]);
    adj[p[0]].push(p[1]);
    adj[p[1]].push(p[0]);
  }
  for (var v=1; v<=5; v++) {
    adj[v].sort(function(a,b) {
      var ia = rowOrder[v].indexOf(a);
      var ib = rowOrder[v].indexOf(b);
      if (ia < 0) ia = 99 + a;
      if (ib < 0) ib = 99 + b;
      return ia - ib;
    });
  }
  return adj;
}

function selectEdge(a,b, fromClick) {
  if (a === b) return;
  selectedEdge = [Math.min(a,b), Math.max(a,b)];
  selectedPair = [a,b];
  selectedVertex = null;
  editMode = 'idle';
  renderAll();
  if (fromClick) {
    showPopup(
      'One edge, two stored entries',
      'The graph has one undirected edge {' + selectedEdge[0] + ',' + selectedEdge[1] + '}. The list representation stores it as two neighbor records, and the matrix stores it as the two symmetric cells (' + selectedEdge[0] + ',' + selectedEdge[1] + ') and (' + selectedEdge[1] + ',' + selectedEdge[0] + ').'
    );
  }
}

function selectVertex(v, fromClick) {
  if (editMode === 'selectingVertices') {
    if (selectedPair.indexOf(v) < 0) {
      if (selectedPair.length >= 2) selectedPair = [];
      selectedPair.push(v);
    }
    selectedVertex = v;
    selectedEdge = selectedPair.length === 2 ? [Math.min(selectedPair[0], selectedPair[1]), Math.max(selectedPair[0], selectedPair[1])] : null;
    renderAll();
    return;
  }
  selectedVertex = v;
  selectedEdge = null;
  selectedPair = [v];
  renderAll();
  if (fromClick) {
    showPopup(
      'Vertex neighborhood',
      'Vertex ' + v + ' has the same neighbor set in the drawing, in its adjacency-list row, and in row and column ' + v + ' of the matrix.'
    );
  }
}

function drawGraph() {
  edgeLayer.clear();
  nodeLayer.clear();

  var ks = Object.keys(edgeSet);
  for (var i=0; i<ks.length; i++) {
    var p = parseKey(ks[i]);
    var a = p[0], b = p[1];
    var pa = graphPos[a], pb = graphPos[b];
    var isSel = selectedEdge && key(a,b) === key(selectedEdge[0], selectedEdge[1]);
    var incident = selectedVertex && (a === selectedVertex || b === selectedVertex);
    var line = edgeLayer.line(pa.x, pa.y, pb.x, pb.y).stroke({
      color: isSel ? colors.orange : (incident ? colors.focusBlue : colors.line),
      width: isSel ? 6 : (incident ? 4.2 : 2.2),
      linecap:'round'
    });
    line.css('cursor','pointer')
      .on('mousemove', (function(aa,bb){ return function(e){ showTooltip('Graph edge {' + aa + ',' + bb + '}', e); }; })(a,b))
      .on('mouseleave', function(){ hideTooltip(); })
      .on('click', (function(aa,bb){ return function(){ selectEdge(aa,bb,true); }; })(a,b));
  }

  if (selectedEdge && !hasEdge(selectedEdge[0], selectedEdge[1])) {
    var p1 = graphPos[selectedEdge[0]], p2 = graphPos[selectedEdge[1]];
    edgeLayer.line(p1.x, p1.y, p2.x, p2.y).stroke({
      color:colors.orange, width:4.2, dasharray:'9 7', linecap:'round'
    });
  }

  for (var v=1; v<=5; v++) {
    var gp = graphPos[v];
    var chosen = selectedVertex === v || selectedPair.indexOf(v) >= 0;
    var node = nodeLayer.circle(60).center(gp.x, gp.y)
      .fill(chosen ? colors.blue : colors.gray)
      .stroke({color:'#000', width:2.2});
    node.css('cursor','pointer')
      .on('mousemove', (function(vv){ return function(e){ showTooltip('Vertex ' + vv, e); }; })(v))
      .on('mouseleave', function(){ hideTooltip(); })
      .on('click', (function(vv){ return function(){ selectVertex(vv,true); }; })(v));
    textCenter(nodeLayer, gp.x, gp.y, v, 41);
  }
  haloText(topLabelLayer, 155, 425, '(a)', 39);
}

function isSelectedListRecord(row, neighbor) {
  if (selectedEdge && hasEdge(selectedEdge[0], selectedEdge[1])) {
    return (row === selectedEdge[0] && neighbor === selectedEdge[1]) ||
           (row === selectedEdge[1] && neighbor === selectedEdge[0]);
  }
  return false;
}

function drawRecord(parent, x, y, row, val, isLast) {
  var w = 100, h = 52, half = 50;
  var pairSel = isSelectedListRecord(row, val);
  var vertexSel = selectedVertex && (row === selectedVertex || val === selectedVertex);
  parent.rect(w,h).move(x,y)
    .fill(pairSel ? colors.yellow : (vertexSel ? colors.yellow2 : colors.gray))
    .stroke({color: pairSel ? colors.orange : (vertexSel ? colors.focusBlue : '#000'), width: pairSel ? 3 : 2});
  parent.line(x+half,y,x+half,y+h).stroke({color:'#000', width:2});
  textCenter(parent, x+half/2, y+h/2, val, 35);
  if (isLast) {
    parent.line(x+half+16, y+h-10, x+w-15, y+10).stroke({color:'#000', width:2.7});
  } else {
    textCenter(parent, x+half+half/2, y+h/2-1, '—', 30);
  }
  var hit = parent.rect(w,h).move(x,y).fill({color:'#fff', opacity:0});
  hit.css('cursor','pointer')
    .on('mousemove', function(e){ showTooltip('List entry: vertex ' + row + ' stores neighbor ' + val, e); })
    .on('mouseleave', function(){ hideTooltip(); })
    .on('click', function(){ selectEdge(row, val, true); });
}

function drawList() {
  listLayer.clear();
  var adj = adjList();
  var arrayX = 438, rowY0 = 55, rowGap = 61, cellW = 58, cellH = 61;
  var recX0 = 520, recGap = 122;

  for (var r=1; r<=5; r++) {
    var y = rowY0 + (r-1)*rowGap;
    haloText(listLayer, 408, y+cellH/2, r, 34);

    listLayer.rect(cellW,cellH).move(arrayX,y)
      .fill(selectedVertex === r ? colors.yellow2 : colors.gray)
      .stroke({color:selectedVertex === r ? colors.focusBlue : '#000', width:selectedVertex === r ? 3 : 2});
    textCenter(listLayer, arrayX+cellW/2, y+cellH/2-2, '—', 30);

    var arrHit = listLayer.rect(cellW,cellH).move(arrayX,y).fill({color:'#fff', opacity:0});
    arrHit.css('cursor','pointer')
      .on('mousemove', (function(rr){ return function(e){ showTooltip('Header for adjacency list of vertex ' + rr, e); }; })(r))
      .on('mouseleave', function(){ hideTooltip(); })
      .on('click', (function(rr){ return function(){ selectVertex(rr,true); }; })(r));

    var vals = adj[r];
    if (vals.length) hArrow(listLayer, arrayX+cellW, y+cellH/2, recX0-8, '#000', 2);
    for (var i=0; i<vals.length; i++) {
      var x = recX0 + i*recGap;
      drawRecord(listLayer, x, y+5, r, vals[i], i === vals.length-1);
      if (i < vals.length-1) hArrow(listLayer, x+100, y+cellH/2, x+recGap-8, '#000', 2);
    }
  }
  haloText(topLabelLayer, 745, 425, '(b)', 39);
}

function matrixValue(i,j){ return i === j ? 0 : (hasEdge(i,j) ? 1 : 0); }

function isSelectedMatrixCell(i,j) {
  if (i === j) return false;
  if (selectedEdge) {
    return (i === selectedEdge[0] && j === selectedEdge[1]) ||
           (i === selectedEdge[1] && j === selectedEdge[0]);
  }
  return false;
}

function drawMatrix() {
  matrixLayer.clear();
  var x0 = 1113, y0 = 55, cell = 54;

  matrixLayer.rect(cell*5, cell*5).move(x0,y0).fill('#fff').stroke({color:'#000', width:2});
  for (var c=1; c<=5; c++) haloText(matrixLayer, x0+(c-0.5)*cell, 26, c, 36);
  for (var r=1; r<=5; r++) haloText(matrixLayer, x0-31, y0+(r-0.5)*cell, r, 36);

  for (var i=1; i<=5; i++) {
    for (var j=1; j<=5; j++) {
      var cx = x0+(j-0.5)*cell, cy = y0+(i-0.5)*cell;
      var pairSel = isSelectedMatrixCell(i,j);
      var vertexSel = selectedVertex && (i === selectedVertex || j === selectedVertex) && matrixValue(i,j) === 1;
      if (pairSel || vertexSel) {
        var rect = matrixLayer.rect(cell-8, cell-8).center(cx,cy)
          .fill(pairSel ? colors.orangeLight : colors.yellow2)
          .stroke({color:pairSel ? colors.orange : colors.focusBlue, width:pairSel ? 3 : 2});
        if (pairSel && selectedEdge && !hasEdge(selectedEdge[0], selectedEdge[1])) rect.attr('stroke-dasharray','7 5');
      }
      textCenter(matrixLayer, cx, cy, matrixValue(i,j), 35);

      var hit = matrixLayer.rect(cell,cell).move(x0+(j-1)*cell, y0+(i-1)*cell).fill({color:'#fff', opacity:0});
      hit.css('cursor','pointer')
        .on('mousemove', (function(ii,jj){ return function(e){ showTooltip('Matrix cell (' + ii + ',' + jj + ') = ' + matrixValue(ii,jj), e); }; })(i,j))
        .on('mouseleave', function(){ hideTooltip(); })
        .on('click', (function(ii,jj){
          return function(){
            if (ii === jj) return;
            if (matrixValue(ii,jj) === 1) selectEdge(ii,jj,true);
            else {
              selectedEdge = [Math.min(ii,jj), Math.max(ii,jj)];
              selectedPair = [ii,jj];
              selectedVertex = null;
              editMode = 'idle';
              renderAll();
            }
          };
        })(i,j));
    }
  }
  haloText(topLabelLayer, 1248, 425, '(c)', 39);
}

function drawFrames() {
  frameLayer.clear();
  panelFrame(8, 35, 330, 382, 'Graph');
  panelFrame(378, 35, 675, 382, 'Adjacency list');
  panelFrame(1065, 35, 340, 382, 'Adjacency matrix');
}

function updateStatus() {
  var s = document.getElementById('editStatus');
  if (!s) return;
  if (editMode === 'selectingVertices') {
    s.textContent = selectedPair.length < 2
      ? 'Edit mode: click two vertices, then press Add/remove.'
      : 'Selected {' + selectedPair[0] + ',' + selectedPair[1] + '}; press Add/remove to toggle it.';
  } else if (selectedEdge) {
    var exists = hasEdge(selectedEdge[0], selectedEdge[1]);
    s.textContent = 'Selected {' + selectedEdge[0] + ',' + selectedEdge[1] + '} ' + (exists ? 'is stored twice in lists and matrix.' : 'is absent; press Add/remove to add it.');
  } else if (selectedVertex) {
    s.textContent = 'Selected vertex ' + selectedVertex + ': compare the same neighbors in all views.';
  } else {
    s.textContent = 'Click an edge, matrix 1, list record, or vertex.';
  }
}

function renderAll() {
  topLabelLayer.clear();
  drawFrames();
  drawGraph();
  drawList();
  drawMatrix();
  updateStatus();
}

function update_representationFocus(v) {
  focusRep = v;
  var sel = document.getElementById('representationFocusInput');
  if (sel) sel.value = v;
  if (v === 'Adjacency list' || v === 'Adjacency matrix') {
    if (!selectedEdge && !selectedVertex) selectVertex(2, false);
    else renderAll();
  } else {
    renderAll();
  }
}

function toggle_representationFocus(on) {
  update_representationFocus(on ? 'Adjacency list' : 'Graph');
}

function trigger_modifyEdge() {
  if (editMode !== 'selectingVertices' && (!selectedPair || selectedPair.length < 2)) {
    editMode = 'selectingVertices';
    selectedPair = [];
    selectedEdge = null;
    selectedVertex = null;
    renderAll();
    return;
  }
  if (!selectedPair || selectedPair.length < 2) {
    editMode = 'selectingVertices';
    renderAll();
    return;
  }
  var a = selectedPair[0], b = selectedPair[1];
  if (a === b) return;
  var existed = hasEdge(a,b);
  setEdge(a,b,!existed);
  selectedEdge = [Math.min(a,b), Math.max(a,b)];
  selectedVertex = null;
  selectedPair = [a,b];
  editMode = 'idle';
  renderAll();
  showPopup(
    existed ? 'Edge removed' : 'Edge added',
    'Changing one undirected edge {' + a + ',' + b + '} changes one graph line, one record in vertex ' + a + "'s list, one record in vertex " + b + "'s list, and the two matrix cells (" + a + ',' + b + ') and (' + b + ',' + a + ').'
  );
}

function trigger_resetOriginal() {
  resetEdgesOnly();
  selectedEdge = null;
  selectedVertex = null;
  selectedPair = [];
  editMode = 'idle';
  focusRep = 'Graph';
  var sel = document.getElementById('representationFocusInput');
  if (sel) sel.value = 'Graph';
  renderAll();
  showPopup('Original graph restored', 'The graph, adjacency lists, and matrix have been reset to the textbook version shown in the figure.');
}

var demoSteps = [
  {
    title:'Same graph, three encodings',
    narration:"The left panel is the graph itself, the middle panel stores each vertex's neighbors in a linked list, and the right panel stores the same information as a 5-by-5 matrix. Focus on any representation to see that the neighbor relationships match across all three.",
    state:{representationFocus:'Graph', modifyEdge:'idle'}
  },
  {
    title:'Trace one edge',
    narration:"Click an edge such as 2-4 in the graph, or click either of its matrix 1s. The demo highlights edge 2-4, the list record 4 in vertex 2's list, the list record 2 in vertex 4's list, and the symmetric matrix cells (2,4) and (4,2).",
    state:{representationFocus:'Adjacency matrix', modifyEdge:'idle'}
  },
  {
    title:"Focus on one vertex's neighborhood",
    narration:'Switch focus to the adjacency list and select vertex 2. Its neighbors 1, 3, 4, and 5 appear as list records, as graph edges incident on vertex 2, and as 1s across row and column 2 of the matrix.',
    state:{representationFocus:'Adjacency list', modifyEdge:'idle'}
  },
  {
    title:'Edit an undirected edge',
    narration:'Select two vertices and press add/remove. The graph line appears or disappears, and the storage updates in pairs: one record in each affected adjacency list and two symmetric matrix entries.',
    state:{representationFocus:'Graph', modifyEdge:'selectingVertices'}
  }
];

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length-1, i));
  var st = demoSteps[currentStep].state;
  focusRep = st.representationFocus || 'Graph';
  editMode = st.modifyEdge || 'idle';
  var sel = document.getElementById('representationFocusInput');
  if (sel) sel.value = focusRep;

  if (currentStep === 0) {
    resetEdgesOnly();
    selectedEdge = null;
    selectedVertex = null;
    selectedPair = [];
  } else if (currentStep === 1) {
    selectedEdge = [2,4];
    selectedVertex = null;
    selectedPair = [2,4];
  } else if (currentStep === 2) {
    selectedEdge = null;
    selectedVertex = 2;
    selectedPair = [2];
  } else if (currentStep === 3) {
    selectedEdge = [1,3];
    selectedVertex = null;
    selectedPair = [1,3];
  }

  var narration = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narration) narration.textContent = demoSteps[currentStep].narration;
  if (label) label.textContent = (currentStep+1) + ' / ' + demoSteps.length + ' — ' + demoSteps[currentStep].title;
  renderAll();
}

function nextStep(){ applyStep(currentStep + 1); }
function prevStep(){ applyStep(currentStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

